      const befund3 = faellig ? `<b>Im Februar zahlen wir ${geld(faellig.betrag)} F\xFChrungsboni aus.</b>` : "<b>Kein Bonus ist f\xE4llig.</b> Abgerechnet wird im Jahresabschluss.";
